extern "C" unsigned int strlen(const char*);

class string_buf
{
public:
  int ref;
  int capacity;
  int char_length;
};

class stringx
{
  char* chars;
  string_buf* my_buf;
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
  stringx& operator=(const stringx&);
  stringx& operator=(const char*);
  void append(const char*, int = -1);
  void append(const stringx&);
  void make_room(int);
  const char* c_str() const { return chars; }
  friend stringx operator+(const char*, const stringx&);
  friend stringx operator+(const stringx&, const char*);
};

inline stringx operator+(const char* lhs, const stringx& rhs)
{
  stringx foo;
  int len = strlen(lhs);
  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx& lhs, const char* rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class script_object
{
public:
  class instance;
  instance* find_instance(const stringx&) const;
};

class script_library_class
{
public:
  virtual ~script_library_class();
protected:
  stringx name;
  int size;
  const char* parent_name;
  const script_library_class* parent;
  int funcs[3];
};

class script_manager;

class slc_script_object_t : public script_library_class
{
  const script_manager& sman;
  script_object* sobj;
public:
  unsigned find_instance(const stringx& n) const;
};

void error(const char*, ...);

unsigned slc_script_object_t::find_instance(const stringx& n) const
{
  script_object::instance* soinst = sobj->find_instance(n);
  if (!soinst)
  {
    stringx err;
    err="script object instance "+n+" not found";
    error(err.c_str());
  }
  return (unsigned)soinst;
}
